args.query:
\dt api.*
\dv api.*
select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='api' order by 1,ordinal_position;
select * from api.app_user;
select * from api.company;

select n.nspname,p.proname,p.prosecdef,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not in ('pg_catalog','information_schema') ;
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select * from pg_policies;
select relname,relrowsecurity,relforcerowsecurity from pg_class where relnamespace='api'::regnamespace and relkind in('r','v');

select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC') order by 2,1,4,3;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC') order by 2,1,3;
select * from api.status;
select conname,conrelid::regclass,pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;

